// 3x3 depthwise conv, stride 1, pad 1; each (channel,row) is an independent task
static const float ZR[640];
static void dw(const float*restrict in,float*restrict out,const float*restrict w,const float*restrict b,int C,int H,int W,int r){
  #pragma omp parallel for collapse(2) schedule(static)
  for(int c=0;c<C;c++)for(int y=0;y<H;y++){
    const float*r1=in+((size_t)c*H+y)*W,*r0=y>0?r1-W:ZR,*r2=y<H-1?r1+W:ZR,*k=w+c*9;
    float*o=out+((size_t)c*H+y)*W,bb=b[c];
    o[0]=R(bb+k[1]*r0[0]+k[2]*r0[1]+k[4]*r1[0]+k[5]*r1[1]+k[7]*r2[0]+k[8]*r2[1]);
    o[W-1]=R(bb+k[0]*r0[W-2]+k[1]*r0[W-1]+k[3]*r1[W-2]+k[4]*r1[W-1]+k[6]*r2[W-2]+k[7]*r2[W-1]);
#ifdef __riscv_vector
    for(int x=1;x<W-1;){
      size_t vl=__riscv_vsetvl_e32m2(W-1-x);
      #define L(p,d) __riscv_vle32_v_f32m2(p+x+d,vl)
      vfloat32m2_t a=VF(vfmv_v_f)(bb,vl);
      a=VF(vfmacc_vf)(a,k[0],L(r0,-1),vl);a=VF(vfmacc_vf)(a,k[1],L(r0,0),vl);a=VF(vfmacc_vf)(a,k[2],L(r0,1),vl);
      a=VF(vfmacc_vf)(a,k[3],L(r1,-1),vl);a=VF(vfmacc_vf)(a,k[4],L(r1,0),vl);a=VF(vfmacc_vf)(a,k[5],L(r1,1),vl);
      a=VF(vfmacc_vf)(a,k[6],L(r2,-1),vl);a=VF(vfmacc_vf)(a,k[7],L(r2,0),vl);a=VF(vfmacc_vf)(a,k[8],L(r2,1),vl);
      if(r)a=VF(vfmax_vf)(a,0,vl);
      __riscv_vse32_v_f32m2(o+x,a,vl);x+=vl;
    }
#else
    for(int x=1;x<W-1;x++)
      o[x]=R(bb+k[0]*r0[x-1]+k[1]*r0[x]+k[2]*r0[x+1]+k[3]*r1[x-1]+k[4]*r1[x]+k[5]*r1[x+1]+k[6]*r2[x-1]+k[7]*r2[x]+k[8]*r2[x+1]);
#endif
  }
}

static void mp(const float*restrict in,float*restrict out,int C,int H,int W){
  int OH=H/2,OW=W/2;
  #pragma omp parallel for collapse(2) schedule(static)
  for(int c=0;c<C;c++)for(int y=0;y<OH;y++){
    const float*a=in+((size_t)c*H+2*y)*W,*b=a+W;float*o=out+((size_t)c*OH+y)*OW;
    for(int x=0;x<OW;x++){float m=a[2*x]>a[2*x+1]?a[2*x]:a[2*x+1],n=b[2*x]>b[2*x+1]?b[2*x]:b[2*x+1];o[x]=m>n?m:n;}
  }
}
static void up(const float*restrict in,float*restrict out,int C,int H,int W){
  #pragma omp parallel for collapse(2) schedule(static)
  for(int c=0;c<C;c++)for(int y=0;y<H;y++){
    const float*a=in+((size_t)c*H+y)*W;float*o=out+((size_t)c*H+y)*4*W;
    for(int x=0;x<W;x++){o[2*x]=o[2*x+1]=o[2*W+2*x]=o[2*W+2*x+1]=a[x];}
  }
}
static void add(const float*restrict a,const float*restrict b,float*restrict o,int n){
  #pragma omp parallel for simd schedule(static)
  for(int i=0;i<n;i++)o[i]=a[i]+b[i];
}
// NCHW -> [HW][C] (+ optional sigmoid)
static void head(const float*restrict in,float*restrict out,int C,int HW,int s){
  #pragma omp parallel for schedule(static)
  for(int p=0;p<HW;p++)for(int c=0;c<C;c++){float v=in[(size_t)c*HW+p];out[p*C+c]=s?1.f/(1.f+expf(-v)):v;}
}

